@import url("chrome://messenger/skin/shared/unifiedToolbarShared.css");
@import url("chrome://messenger/skin/shared/serverMenuItems.css");

:root {
  --unified-toolbar-padding: 4px;
  --unified-drag-space: 30px;
  --unified-customization-padding: 30px;
  /* minimal possible toolbar height */
  --unified-toolbar-minimal-height: 30px;
  /* button border + button padding */
  --unified-toolbar-button-spacing-height: calc(2px + var(--button-padding) * 2);
  /* 1lh for the text */
  --unified-toolbar-content-min-height: calc(1lh + var(--unified-toolbar-button-spacing-height));
  /* searchbar field height + border + block padding */
  --unified-toolbar-searchbar-height: calc(1.45lh + 4px);

  &[uidensity="compact"] {
    --unified-toolbar-padding: 1px;
    --unified-drag-space: 15px;
    --unified-toolbar-minimal-height: 24px;
  }

  &[uidensity="touch"] {
    --unified-toolbar-padding: 7px;
  }

  &[sizemode="fullscreen"],
  &:not([customtitlebar]) {
    --unified-drag-space: 3px;
  }

  & .icons-above-text {
    /* icon plus gap is 19px, 1lh for the text */
    --unified-toolbar-content-min-height: calc(19px + 1lh + var(--unified-toolbar-button-spacing-height));
  }

  & .icons-only {
    /* icon size is 16px */
    --unified-toolbar-content-min-height: calc(16px + var(--unified-toolbar-button-spacing-height));
  }
}

unified-toolbar {
  display: block;
  border-block-end: 1px solid rgba(0, 0, 0, 0.15);
}

#unifiedToolbarContainer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  -moz-window-dragging: drag;
  inline-size: 100vw;

  /* minheight for the macOS titlebar */
  .customizingUnifiedToolbar & {
    min-block-size: 22px;
  }

  & .titlebar-buttonbox-container {
    flex: 0 0 auto;

    @media (-moz-platform: windows) or (-moz-platform: linux) {
      align-self: stretch;
    }
  }

  @media (-moz-gtk-csd-reversed-placement) {
    flex-direction: row-reverse;
  }
}

#unifiedToolbar {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  padding-block: var(--unified-toolbar-padding);
  min-inline-size: 0;
  overflow: hidden;

  & .button:is(.toolbar-button, .unified-toolbar-button) {
    margin-block: 0;
  }
}

#unifiedToolbarContent {
  flex: 1 1 auto;
  min-block-size: max(var(--unified-toolbar-minimal-height), var(--unified-toolbar-searchbar-height), var(--unified-toolbar-content-min-height));
  margin: 0;
  /* Padding needed for the children's focus ring. */
  padding-block: 3px;
  padding-inline: var(--unified-drag-space) 3px;
